<script setup>
import { ref, watch } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MInput from '../../../components/mds/MInput.vue';
const props=defineProps({rows:{type:Array,default:()=>[]},total:Number,page:Number,pageSize:Number,search:String,canCreate:Boolean});const emit=defineEmits(['search','page','open','create']);const query=ref(props.search||'');watch(()=>props.search,(value)=>{query.value=value||'';});function submit(){emit('search',query.value.trim());}
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><div class="mx-auto max-w-[1200px] space-y-4"><header class="rounded-lg bg-[var(--mds-bg)] px-5 py-4 shadow-[var(--mds-shadow-card)]"><div class="flex flex-wrap items-start justify-between gap-4"><div><h1 class="text-[20px] font-semibold leading-7">Nhà cung cấp</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Danh sách chỉ hiển thị trường được máy chủ cho phép xem.</p></div><MButton v-if="canCreate" variant="primary" @click="emit('create')">Thêm nhà cung cấp</MButton></div><form class="mt-4 flex max-w-[560px] gap-2" @submit.prevent="submit"><MInput v-model="query" placeholder="Tìm tên, ngành nghề, dịch vụ…"/><MButton variant="primary" @click="submit">Tìm</MButton></form></header><section class="overflow-hidden rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]"><div class="flex items-center justify-between border-b border-[var(--mds-border-light)] px-5 py-3"><p class="text-[13px] text-[var(--mds-text-secondary)]">{{ Number(total||0).toLocaleString('vi-VN') }} nhà cung cấp</p><p class="text-[12px] text-[var(--mds-text-secondary)]">Trang {{ page }}</p></div><div v-if="rows.length" class="overflow-x-auto"><table class="w-full min-w-[760px] text-left"><thead class="bg-[var(--mds-bg-page)] text-[12px] font-medium text-[var(--mds-text-secondary)]"><tr><th class="px-5 py-3">Nhà cung cấp</th><th class="px-3 py-3">Ngành nghề</th><th class="px-3 py-3">Dịch vụ</th><th class="px-3 py-3">Liên hệ</th><th class="px-5 py-3"></th></tr></thead><tbody class="divide-y divide-[var(--mds-border-light)]"><tr v-for="row in rows" :key="row.id" class="hover:bg-[var(--mds-bg-page)]"><td class="px-5 py-3"><strong class="block text-[13px]">{{ row.name }}</strong></td><td class="px-3 py-3 text-[13px]">{{ row.industry }}</td><td class="px-3 py-3 text-[13px]">{{ row.services }}</td><td class="px-3 py-3 text-[13px]">{{ row.contact }}</td><td class="px-5 py-3 text-right"><MButton variant="link" @click="emit('open',row.id)">Mở hồ sơ</MButton></td></tr></tbody></table></div><MEmptyState v-else title="Chưa có nhà cung cấp" description="Thử đổi từ khóa hoặc tạo hồ sơ mới."/></section><footer class="flex justify-end gap-2"><MButton variant="neutral" :disabled="page<=1" @click="emit('page',page-1)">Trang trước</MButton><MButton variant="neutral" :disabled="page*pageSize>=total" @click="emit('page',page+1)">Trang sau</MButton></footer></div></section></template>
